 insight_project_files_free(sink.accepted);insight_project_files_free(policy);pattern_sync(root,path,project);typed_sync(root,path,project);automatic_masks(root,path,project);g_unlink(path);g_unlink(one);g_unlink(two);g_rmdir(root);g_free(cwd);g_free(name);g_free(root);g_free(path);g_free(one);g_free(two);g_free(project);g_print("Master sync: background snapshots, additions/removals, invalid preservation, throttled errors, guarded writeback, exact rollback, external conflict, supersession and shutdown passed\n");return 0;
